(function(E){ const x = E["exam-01"] = E["exam-01"] || {units:{}}; (x.units = x.units || {})["x01-s"] = {"id":"x01-s","patterns":["S1-frame","S1-people","S2-experience","S3-tourism","TR-short","PARA-discuss"],"title":{"en":"Speaking","tr":"Speaking","fa":"Speaking (صحبت کردن)"},"objective":{"en":"In this lesson you will learn to take the whole Speaking test: answer everyday questions in two or three sentences, talk for two minutes about an experience, and discuss general questions with a view, a reason and an example.","tr":"Bu derste Speaking sınavının tamamını yapmayı öğreneceksin: günlük soruları iki üç cümleyle cevaplayacak, bir deneyim hakkında iki dakika konuşacak ve genel soruları bir görüş, bir neden ve bir örnekle tartışacaksın.","fa":"در این درس یاد می‌گیری کل آزمون Speaking را انجام بدهی: به سؤال‌های روزمره با دو سه جمله جواب بدهی، دو دقیقه درباره‌ی یک تجربه حرف بزنی و درباره‌ی سؤال‌های کلی با یک نظر، یک دلیل و یک مثال بحث کنی."},"sessions":[["explain"],["sets"],["exit"]],"explain":{"title":{"en":"Speaking: Parts 1, 2 and 3","tr":"Speaking: Part 1, 2 ve 3","fa":"Speaking: بخش‌های ۱، ۲ و ۳"},"objective":{"en":"In this lesson you will learn to take the whole Speaking test: answer everyday questions in two or three sentences, talk for two minutes about an experience, and discuss general questions with a view, a reason and an example.","tr":"Bu derste Speaking sınavının tamamını yapmayı öğreneceksin: günlük soruları iki üç cümleyle cevaplayacak, bir deneyim hakkında iki dakika konuşacak ve genel soruları bir görüş, bir neden ve bir örnekle tartışacaksın.","fa":"در این درس یاد می‌گیری کل آزمون Speaking را انجام بدهی: به سؤال‌های روزمره با دو سه جمله جواب بدهی، دو دقیقه درباره‌ی یک تجربه حرف بزنی و درباره‌ی سؤال‌های کلی با یک نظر، یک دلیل و یک مثال بحث کنی."},"stats":[{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"11-14 min","tr":"11-14 dk","fa":"۱۱ تا ۱۴ دقیقه"}},{"label":{"en":"Parts","tr":"Kısım","fa":"بخش"},"value":"3"},{"label":{"en":"Part 2 talk","tr":"Part 2 konuşması","fa":"صحبت Part 2"},"value":{"en":"2 min","tr":"2 dk","fa":"۲ دقیقه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: clothes, finding your way, travel","tr":"Bu sınav: kıyafetler, yol bulmak, seyahat","fa":"این آزمون: لباس، پیدا کردن راه، سفر"},"intro":{"en":"The three parts are linked: Part 1 is about you, Part 2 is one experience on a card, and Part 3 widens the Part 2 topic to people in general. Experiences are the most common Part 2 card.","tr":"Üç kısım birbirine bağlıdır: Part 1 seninle ilgili, Part 2 karttaki bir deneyim ve Part 3, Part 2 konusunu genel olarak insanlara genişletir. Deneyimler en sık çıkan Part 2 kartıdır.","fa":"سه بخش به هم وصل‌اند: Part 1 درباره‌ی خودت است، Part 2 یک تجربه روی کارت و Part 3 موضوع Part 2 را به آدم‌ها به‌طور کلی گسترش می‌دهد. تجربه‌ها رایج‌ترین کارت Part 2 هستند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x01-s1-ctx","exam":true,"patterns":["S1-frame","S1-people"],"often":{"pattern":"S1-people","n":9,"of":40,"label":{"en":"Comes up often in the real exam: 9 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 9’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۹ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 1: you, then clothes","tr":"Part 1: sen, sonra kıyafetler","fa":"Part 1: خودت، بعد لباس"},"asks":{"en":"The examiner checks your name and asks about your work, studies or home, then four questions on one everyday topic. Here the topic is clothes.","tr":"Sınav görevlisi adını kontrol eder, işini, okulunu ya da evini sorar, sonra günlük bir konuda dört soru sorar. Burada konu kıyafetler.","fa":"ممتحن اسمت را چک می‌کند، درباره‌ی کار، درس یا خانه‌ات می‌پرسد و بعد چهار سؤال درباره‌ی یک موضوع روزمره. این‌جا موضوع لباس است."},"fields":["Work or studies","Home","What you usually wear","Weekdays and weekends","Buying clothes","Uniforms"],"words":[{"a":"casual clothes","b":"jeans and a T-shirt / something comfortable","tr":"günlük kıyafetler","fa":"لباس راحت"},{"a":"smart clothes","b":"a suit / something formal","tr":"şık kıyafetler","fa":"لباس رسمی"},{"a":"go shopping for clothes","b":"buy new things to wear","tr":"kıyafet alışverişine gitmek","fa":"خرید لباس"},{"a":"it depends","b":"it depends on the weather / where I’m going","tr":"duruma bağlı","fa":"بستگی دارد"},{"a":"usually","b":"most of the time / normally","tr":"genellikle","fa":"معمولاً"},{"a":"once in a while","b":"now and then / not very often","tr":"arada bir","fa":"گاهی"},{"a":"a uniform","b":"what everyone at school or work has to wear","tr":"üniforma","fa":"یونیفرم"},{"a":"fashion","b":"what is popular now / trends","tr":"moda","fa":"مد"},{"a":"second-hand","b":"used before by someone else","tr":"ikinci el","fa":"دست‌دوم"},{"a":"comfortable","b":"easy to wear all day","tr":"rahat","fa":"راحت"}],"traps":[{"en":"One-word answers: \"Yes.\" or \"Jeans.\" Give the answer and one reason or detail.","tr":"Tek kelimelik cevaplar: \"Yes.\" ya da \"Jeans.\" Cevabı ve bir neden ya da ayrıntıyı ver.","fa":"جواب‌های یک‌کلمه‌ای: «Yes.» یا «Jeans.». جواب و یک دلیل یا جزئیات بده."},{"en":"A memorised speech: Part 1 is a short, natural conversation. Two or three sentences are enough.","tr":"Ezberlenmiş bir konuşma: Part 1 kısa ve doğal bir sohbettir. İki üç cümle yeter.","fa":"سخنرانیِ حفظ‌شده: Part 1 یک گفتگوی کوتاه و طبیعی است. دو سه جمله کافی است."}],"example":{"text":"Q: \"Do you like shopping for clothes?\"","item":"Which answer is the right length?","answer":"Not really, to be honest. I find big shops tiring, so I usually buy things online.","why":{"en":"An answer, then a reason and a detail: about ten seconds.","tr":"Bir cevap, sonra bir neden ve bir ayrıntı: yaklaşık on saniye.","fa":"یک جواب، بعد یک دلیل و یک جزئیات: حدود ده ثانیه."}}},{"id":"x01-s2-ctx","exam":true,"patterns":["S2-experience","PARA-discuss"],"often":{"pattern":"S2-experience","n":17,"of":40,"label":{"en":"Comes up often in the real exam: 17 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 17’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۷ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 2: a time you found your way","tr":"Part 2: yolunu bulduğun bir an","fa":"Part 2: وقتی راهت را پیدا کردی"},"asks":{"en":"A cue card asks you to describe an experience: here, using a map or an app in a place you did not know. You have one minute to make notes and then talk for up to two minutes.","tr":"Bir konu kartı bir deneyimi anlatmanı istiyor: burada bilmediğin bir yerde harita ya da uygulama kullanmak. Not almak için bir dakikan var, sonra iki dakikaya kadar konuşursun.","fa":"یک کارت موضوع از تو می‌خواهد تجربه‌ای را توصیف کنی: این‌جا استفاده از نقشه یا اپ در جایی که نمی‌شناختی. یک دقیقه برای یادداشت داری و بعد تا دو دقیقه حرف می‌زنی."},"fields":["Where you were","What you were looking for","How you used the map or app","Whether it helped, and why"],"words":[{"a":"I got lost","b":"I couldn’t find my way","tr":"kayboldum","fa":"گم شدم"},{"a":"the signal dropped","b":"my phone had no connection","tr":"sinyal gitti","fa":"آنتن قطع شد"},{"a":"a landmark","b":"a building or place that is easy to recognise","tr":"simge yapı, işaret noktası","fa":"نشانه‌ی شاخص"},{"a":"turned out","b":"in the end it was","tr":"sonunda ... çıktı","fa":"معلوم شد"},{"a":"directions","b":"instructions on how to get somewhere","tr":"yol tarifi","fa":"نشانی و مسیر"},{"a":"a shortcut","b":"a quicker way","tr":"kestirme","fa":"میان‌بر"},{"a":"at first","b":"in the beginning","tr":"ilk başta","fa":"اولش"},{"a":"eventually","b":"after a long time / in the end","tr":"sonunda","fa":"بالاخره"},{"a":"it saved me","b":"without it I would have...","tr":"beni kurtardı","fa":"نجاتم داد"},{"a":"looking back","b":"when I think about it now","tr":"geriye bakınca","fa":"وقتی حالا فکرش را می‌کنم"}],"traps":[{"en":"Listing the prompts like a form: \"Where: Lisbon. What: a museum.\" Tell it as a story, in time order.","tr":"Maddeleri form gibi sıralamak: \"Nerede: Lizbon. Ne: bir müze.\" Bir hikâye gibi, zaman sırasıyla anlat.","fa":"نکته‌ها را مثل فرم فهرست کردن: «کجا: لیسبون. چه: یک موزه.» آن را مثل یک داستان، به ترتیب زمان تعریف کن."},{"en":"Stopping after one minute. The explain line (did it help, and why) is where you reach two minutes.","tr":"Bir dakika sonra durmak. Açıklama satırı (yardımcı oldu mu, neden) iki dakikaya ulaştığın yerdir.","fa":"بعد از یک دقیقه ساکت شدن. خط توضیح (کمک کرد یا نه و چرا) جایی است که به دو دقیقه می‌رسی."}],"example":{"text":"Notes (one minute): Lisbon · old town · small restaurant · app, no signal · asked a waiter · found it → app helped only half","item":"How do you start?","answer":"I’d like to talk about a trip to Lisbon two years ago, when I was trying to find a tiny restaurant in the old town.","why":{"en":"The first sentence answers \"where\" and \"what\" at once and sets the scene.","tr":"İlk cümle \"nerede\" ve \"ne\" sorularını hemen cevaplıyor ve sahneyi kuruyor.","fa":"جمله‌ی اول همان اول به «کجا» و «چه» جواب می‌دهد و صحنه را می‌چیند."}}},{"id":"x01-s3-ctx","exam":true,"patterns":["S3-tourism","PARA-discuss","TR-short"],"often":{"pattern":"S3-tourism","n":7,"of":40,"label":{"en":"Comes up often in the real exam: 7 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 3: travel information and tourist sites","tr":"Part 3: seyahat bilgisi ve turistik yerler","fa":"Part 3: اطلاعات سفر و جاذبه‌های گردشگری"},"asks":{"en":"The examiner asks six general questions linked to the Part 2 topic: how people find information when they travel, and how tourism affects famous places.","tr":"Sınav görevlisi Part 2 konusuyla bağlantılı altı genel soru sorar: insanlar seyahat ederken bilgiyi nasıl bulur ve turizm ünlü yerleri nasıl etkiler.","fa":"ممتحن شش سؤال کلی مرتبط با موضوع Part 2 می‌پرسد: آدم‌ها در سفر چطور اطلاعات پیدا می‌کنند و گردشگری چه اثری روی جاهای معروف دارد."},"fields":["Ways to find information","Reliable or not","Travelling without a plan","Crowded sites","Limiting visitors","Local people and tourism"],"words":[{"a":"reliable","b":"you can trust it","tr":"güvenilir","fa":"قابل‌اعتماد"},{"a":"up to date","b":"the latest information","tr":"güncel","fa":"به‌روز"},{"a":"overcrowded","b":"too many visitors","tr":"aşırı kalabalık","fa":"بیش از حد شلوغ"},{"a":"a tourist attraction","b":"a famous site / a landmark","tr":"turistik yer","fa":"جاذبه‌ی گردشگری"},{"a":"limit numbers","b":"a daily cap / timed tickets","tr":"sayıyı sınırlamak","fa":"محدود کردن تعداد"},{"a":"the local economy","b":"jobs and income for people who live there","tr":"yerel ekonomi","fa":"اقتصاد محلی"},{"a":"spontaneous","b":"without a plan","tr":"plansız, kendiliğinden","fa":"بی‌برنامه، خودجوش"},{"a":"reviews","b":"what other travellers say online","tr":"yorumlar","fa":"نظرهای کاربران"},{"a":"on the other hand","b":"however / that said","tr":"öte yandan","fa":"از طرف دیگر"},{"a":"in the long run","b":"over many years","tr":"uzun vadede","fa":"در درازمدت"}],"traps":[{"en":"A one-sentence opinion. Part 3 wants a view, a reason, an example and, when it helps, the other side.","tr":"Tek cümlelik bir görüş. Part 3 bir görüş, bir neden, bir örnek ve gerektiğinde karşı tarafı ister.","fa":"نظری در یک جمله. Part 3 یک نظر، یک دلیل، یک مثال و هرجا لازم بود طرف مقابل را می‌خواهد."},{"en":"Talking only about yourself. Part 3 questions are about people in general and society, not your own trip.","tr":"Yalnızca kendinden söz etmek. Part 3 soruları kendi gezin hakkında değil, genel olarak insanlar ve toplum hakkındadır.","fa":"فقط از خودت حرف زدن. سؤال‌های Part 3 درباره‌ی آدم‌ها به‌طور کلی و جامعه‌اند، نه سفر خودت."}],"example":{"text":"Q: \"Why do some people prefer guided tours?\"","item":"Which answer has a view, a reason and an example?","answer":"I think many people like the security of a tour, because everything is organised for them. For instance, older travellers often don’t want to worry about tickets or transport.","why":{"en":"View (I think...), reason (because...), example (For instance...).","tr":"Görüş (I think...), neden (because...), örnek (For instance...).","fa":"نظر (I think...)، دلیل (because...)، مثال (For instance...)."}}},{"id":"S2-exp-journey","ctx":["S2-experience","S2-exp-journey"],"title":{"en":"Journeys and visits","tr":"Yolculuklar ve ziyaretler","fa":"سفرها و دیدارها"},"asks":{"en":"A card about going somewhere: a long car journey, a visit to a relative, a visit to a workplace, a time you used tourist information. The prompts ask where, who with, what happened and why you remember it.","tr":"Bir yere gitmek hakkında kart: uzun bir araba yolculuğu, bir akrabayı ziyaret, bir iş yerini ziyaret, turist danışmayı kullandığın bir an. Maddeler nereye, kiminle, ne olduğunu ve neden hatırladığını sorar.","fa":"کارتی درباره‌ی رفتن به جایی: یک سفر طولانی با ماشین، دیدار با یک خویشاوند، بازدید از یک محل کار، وقتی که از اطلاعات گردشگری استفاده کردی. بندها می‌پرسند کجا، با چه کسی، چه اتفاقی افتاد و چرا یادت مانده."},"fields":["Describe a long journey you made by car.","Describe a time you visited a relative.","Describe a time you visited a workplace.","Describe a time you used tourist information."],"words":[{"a":"trip","b":"journey / drive","tr":"yolculuk","fa":"سفر"},{"a":"we left","b":"we set off at dawn","tr":"şafakta yola çıktık","fa":"سپیده‌دم راه افتادیم"},{"a":"we arrived","b":"we finally got there","tr":"sonunda vardık","fa":"بالاخره رسیدیم"},{"a":"the road","b":"the motorway / a mountain road","tr":"otoyol, dağ yolu","fa":"بزرگراه، جاده‌ی کوهستانی"},{"a":"it took long","b":"it took us nine hours","tr":"dokuz saat sürdü","fa":"نُه ساعت طول کشید"},{"a":"a stop","b":"we stopped off at","tr":"... -de mola verdik","fa":"سر راه در ... توقف کردیم"},{"a":"we got lost","b":"we took a wrong turning","tr":"yanlış yola saptık","fa":"راه را اشتباه رفتیم"},{"a":"my relatives","b":"my grandparents / my cousins","tr":"büyükannem ve büyükbabam / kuzenlerim","fa":"پدربزرگ و مادربزرگ / عموزاده‌ها"},{"a":"they welcomed us","b":"they made us feel at home","tr":"bizi evimizdeymiş gibi hissettirdiler","fa":"حسابی تحویلمان گرفتند"},{"a":"I saw how they work","b":"they showed me round","tr":"beni gezdirdiler","fa":"دور و اطراف را نشانم دادند"},{"a":"tired","b":"exhausted / worn out","tr":"bitkin","fa":"خسته و کوفته"},{"a":"worth it","b":"it was well worth the effort","tr":"zahmetine değdi","fa":"به زحمتش می‌ارزید"}],"traps":[{"en":"A journey is not a list of places. Choose one or two moments and describe them in detail.","tr":"Bir yolculuk yerlerin listesi değildir. Bir iki anı seç ve ayrıntılı anlat.","fa":"سفر فهرست جاها نیست. یکی دو لحظه را انتخاب کن و با جزئیات توصیف کن."},{"en":"Keep the time order clear with \"at first\", \"after a few hours\", \"by the time we arrived\".","tr":"\"Önce\", \"birkaç saat sonra\", \"vardığımızda\" ile zaman sırasını net tut.","fa":"با «at first»، «after a few hours»، «by the time we arrived» ترتیب زمانی را روشن نگه دار."}],"example":{"lines":[["Candidate","We set off at dawn, because my father wanted to avoid the traffic."],["Candidate","After about four hours, we took a wrong turning and ended up on a tiny mountain road."],["Candidate","By the time we arrived at my grandparents’ village, it was already dark."]],"item":"Which phrases keep the time order clear?","answer":"\"We set off at dawn\", \"After about four hours\", \"By the time we arrived\".","why":{"en":"Time phrases let the listener follow the journey without a list of places.","tr":"Zaman ifadeleri, bir yer listesi olmadan dinleyenin yolculuğu takip etmesini sağlar.","fa":"عبارت‌های زمانی به شنونده اجازه می‌دهند بدون فهرست جاها سفر را دنبال کند."}},"ideas":["why you went","who was with you","one thing that went wrong on the way","the best moment","why you still remember it (explain)"],"general":true,"patterns":["S2-experience"],"often":{"pattern":"S2-experience","n":17,"of":40,"label":{"en":"Comes up often in the real exam: 17 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 17’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۷ آزمون از ۴۰ آزمونِ اخیر"}}},{"id":"S3-tourism","ctx":["S3-tourism"],"title":{"en":"Tourism and travel","tr":"Turizm ve seyahat","fa":"گردشگری و سفر"},"asks":{"en":"General questions linked to the Part 2 card, about holidays, free museums, attractions, tourism and local people, and travel in cities. The examiner wants an opinion, a reason, an example and, when it helps, the other side.","tr":"Part 2 kartına bağlı, tatiller, ücretsiz müzeler, turistik yerler, turizm ve yerel halk, şehir içi ulaşım hakkında genel sorular. Sınav görevlisi bir görüş, bir neden, bir örnek ve gerektiğinde karşı tarafı ister.","fa":"سؤال‌های کلی مرتبط با کارت Part 2، درباره‌ی تعطیلات، موزه‌های رایگان، جاذبه‌ها، گردشگری و مردم محلی، و رفت‌وآمد در شهر. ممتحن یک نظر، یک دلیل، یک مثال و هرجا لازم بود طرف مقابل را می‌خواهد."},"fields":["What kinds of holiday are popular in your country?","Should museums be free for local people?","Is tourism good for the people who live in tourist areas?","Why are some attractions disappointing?","Is it better to travel alone or in a group?"],"words":[{"a":"tourists","b":"visitors","tr":"ziyaretçiler","fa":"بازدیدکننده‌ها"},{"a":"a famous place","b":"a tourist attraction / a landmark","tr":"turistik yer","fa":"جاذبه‌ی گردشگری"},{"a":"too many tourists","b":"overcrowding / mass tourism","tr":"kitle turizmi","fa":"گردشگری انبوه"},{"a":"local people","b":"residents / locals","tr":"yerel halk","fa":"مردم محلی"},{"a":"it brings money","b":"it boosts the local economy","tr":"yerel ekonomiyi canlandırır","fa":"اقتصاد محلی را رونق می‌دهد"},{"a":"prices go up","b":"the cost of living rises","tr":"hayat pahalılaşır","fa":"هزینه‌ی زندگی بالا می‌رود"},{"a":"relaxing holiday","b":"a beach holiday / a break","tr":"dinlenme tatili","fa":"تعطیلات استراحتی"},{"a":"active holiday","b":"sightseeing / adventure travel","tr":"gezi, macera turizmi","fa":"گشت‌وگذار، سفر ماجراجویانه"},{"a":"disappointing","b":"it didn't live up to expectations","tr":"beklentiyi karşılamadı","fa":"به انتظار نمی‌ارزید"},{"a":"free entry","b":"no admission charge","tr":"giriş ücretsiz","fa":"ورود رایگان"},{"a":"culture","b":"heritage / traditions","tr":"miras, gelenekler","fa":"میراث و سنت‌ها"},{"a":"respect","b":"behave responsibly","tr":"sorumlu davranmak","fa":"مسئولانه رفتار کردن"}],"traps":[{"en":"Avoid describing your own holiday at length; that was Part 2. Part 3 asks what is true in general.","tr":"Kendi tatilini uzun uzun anlatma; o Part 2’ydi. Part 3 genel olarak neyin doğru olduğunu sorar.","fa":"تعطیلات خودت را مفصل تعریف نکن؛ آن مال Part 2 بود. Part 3 می‌پرسد چه چیزی به‌طور کلی درست است."},{"en":"Compare past and present when the question invites it: \"Fifty years ago..., but nowadays...\".","tr":"Soru uygunsa geçmişle bugünü karşılaştır: \"Elli yıl önce..., ama günümüzde...\".","fa":"وقتی سؤال اجازه می‌دهد گذشته و حال را مقایسه کن: «پنجاه سال پیش...، ولی امروزه...»."}],"example":{"lines":[["Examiner","Is tourism good for the people who live in tourist areas?"],["Candidate","Mostly, yes, because it creates jobs in hotels, restaurants and shops."],["Candidate","In my hometown, for instance, my cousin opened a small guesthouse that supports her whole family."],["Candidate","On the other hand, rents have gone up so much that some young people can’t afford to live there any more."]],"item":"Which moves does the answer make?","answer":"Opinion with a reason, a real example, then the other side.","why":{"en":"The example makes the reason believable; the other side shows balance.","tr":"Örnek nedeni inandırıcı kılıyor; karşı taraf dengeyi gösteriyor.","fa":"مثال دلیل را باورپذیر می‌کند؛ طرف مقابل نشان‌دهنده‌ی تعادل است."}},"ideas":["tourism brings jobs but raises rents","free museums help families and students","famous sights are often crowded and overpriced","travelling alone gives freedom; groups give safety"],"general":true,"patterns":["S3-tourism"],"often":{"pattern":"S3-tourism","n":7,"of":40,"label":{"en":"Comes up often in the real exam: 7 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Three parts, one examiner","tr":"Üç kısım, bir sınav görevlisi","fa":"سه بخش، یک ممتحن"},"body":{"en":"Part 1 (4-5 minutes): questions about you and one everyday topic. Part 2 (3-4 minutes): one minute to prepare, then up to two minutes alone, then one short question. Part 3 (4-5 minutes): a discussion of general questions. The test is recorded.","tr":"Part 1 (4-5 dakika): seninle ve günlük bir konuyla ilgili sorular. Part 2 (3-4 dakika): bir dakika hazırlık, sonra iki dakikaya kadar tek başına konuşma, sonra kısa bir soru. Part 3 (4-5 dakika): genel soruların tartışması. Sınav kaydedilir.","fa":"Part 1 (۴ تا ۵ دقیقه): سؤال‌هایی درباره‌ی خودت و یک موضوع روزمره. Part 2 (۳ تا ۴ دقیقه): یک دقیقه آماده شدن، بعد تا دو دقیقه حرف زدن به‌تنهایی و بعد یک سؤال کوتاه. Part 3 (۴ تا ۵ دقیقه): بحث درباره‌ی سؤال‌های کلی. آزمون ضبط می‌شود."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"One move for each part","tr":"Her kısım için bir hamle","fa":"برای هر بخش یک حرکت"},"steps":[{"en":"Part 1: answer, then add a reason or a detail. Two or three sentences.","tr":"Part 1: cevapla, sonra bir neden ya da ayrıntı ekle. İki üç cümle.","fa":"Part 1: جواب بده، بعد یک دلیل یا جزئیات اضافه کن. دو سه جمله."},{"en":"Part 2: in the minute, write one key word for each line of the card.","tr":"Part 2: o bir dakikada kartın her satırı için bir anahtar kelime yaz.","fa":"Part 2: در آن یک دقیقه برای هر خط کارت یک کلیدواژه بنویس."},{"en":"Part 2: tell it in time order and spend the most time on the explain line.","tr":"Part 2: zaman sırasıyla anlat ve en çok zamanı açıklama satırına ayır.","fa":"Part 2: به ترتیب زمان تعریف کن و بیشترین وقت را روی خط توضیح بگذار."},{"en":"Part 3: give a view, a reason, an example, and the other side when it helps.","tr":"Part 3: bir görüş, bir neden, bir örnek ve gerektiğinde karşı tarafı ver.","fa":"Part 3: یک نظر، یک دلیل، یک مثال و هرجا کمک کرد طرف مقابل را بگو."}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Past tenses for the story, opinion phrases for Part 3","tr":"Hikâye için geçmiş zamanlar, Part 3 için görüş ifadeleri","fa":"زمان‌های گذشته برای داستان، عبارت‌های نظر برای Part 3"},"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["the scene (past continuous)","I was walking through the old town when..."],["the events (past simple)","I opened the app and followed the arrow."],["looking back","Looking back, I realise that..."],["a view","I’d say that... / In my view,..."],["the other side","That said, some people feel that..."]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"A Part 3 answer, step by step","tr":"Bir Part 3 cevabı, adım adım","fa":"یک جواب Part 3، قدم به قدم"},"instruction":"Examiner: \"Do you think people read printed newspapers less than in the past?\"","item":"Answer with four moves.","answer":"Yes, definitely. Most people get their news on their phones now, because it’s free and instant. My parents, for example, cancelled their newspaper years ago. That said, some older readers still prefer paper, because it’s easier on the eyes.","walk":[{"en":"View: \"Yes, definitely.\"","tr":"Görüş: \"Yes, definitely.\"","fa":"نظر: «Yes, definitely.»"},{"en":"Reason and example: phones are free and instant; the parents cancelled the paper.","tr":"Neden ve örnek: telefonlar ücretsiz ve anında; ebeveynler gazeteyi iptal etti.","fa":"دلیل و مثال: گوشی رایگان و فوری است؛ پدر و مادر روزنامه را لغو کردند."},{"en":"The other side: \"That said, some older readers...\"","tr":"Karşı taraf: \"That said, some older readers...\"","fa":"طرف مقابل: «That said, some older readers...»"}]},"quick":{"prompt":"Part 1. Examiner: \"Do you like wearing hats?\" Which answer is best?","options":["No.","Hats have a long history in many countries, and there are many kinds of hats, such as...","Not really. I only wear one in winter, when it’s freezing."],"correct":2,"why":{"en":"An answer plus a short reason. \"No.\" is too short; the answer about the history of hats is a speech, not a conversation.","tr":"Bir cevap ve kısa bir neden. \"No.\" çok kısa; şapkaların tarihini anlatan cevap sohbet değil, nutuk.","fa":"یک جواب و یک دلیل کوتاه. «No.» خیلی کوتاه است؛ جوابی که تاریخچه‌ی کلاه را تعریف می‌کند سخنرانی است، نه گفتگو."}},"remember":{"en":"Part 1 short and natural, Part 2 a story in order, Part 3 view, reason, example.","tr":"Part 1 kısa ve doğal, Part 2 sıralı bir hikâye, Part 3 görüş, neden, örnek.","fa":"Part 1 کوتاه و طبیعی، Part 2 داستانی به ترتیب، Part 3 نظر، دلیل، مثال."},"type":"explain","id":"c-x01-s-e","course":"ielts-exams","exam":"exam-01","unit":"x01-s"},"sets":{"title":{"en":"The Speaking test","tr":"Speaking sınavı","fa":"آزمون Speaking"},"note":{"en":"Do the three parts in order, without a break, as in the real test. Record yourself if you can, then use the self-check under each part.","tr":"Gerçek sınavdaki gibi üç kısmı sırayla ve ara vermeden yap. Yapabilirsen kendini kaydet, sonra her kısmın altındaki öz değerlendirmeyi kullan.","fa":"سه بخش را به ترتیب و بدون مکث انجام بده، مثل آزمون واقعی. اگر می‌توانی صدایت را ضبط کن و بعد از خودارزیابیِ زیر هر بخش استفاده کن."},"sequential":true,"examinerVoice":{"accent":"British (standard Southern)","gender":"F","tts":{"engine":"kokoro","voice":"bf_alice"},"role":"Examiner"},"sets":[{"part":"Part 1","ctx":["S1-frame","S1-people"],"minutes":[4,5],"title":{"en":"Part 1: about you, then clothes","tr":"Part 1: senin hakkında, sonra kıyafetler","fa":"Part 1: درباره‌ی خودت، بعد لباس"},"examinerIntro":["Good morning. My name is Sarah Lane. Can you tell me your full name, please?","Thank you. And can I see your identification, please?","Thank you. Now, in this first part, I’d like to ask you some questions about yourself."],"frame":["Do you work or are you a student?","What do you enjoy most about your work or your studies?","Let’s talk about where you live. Do you live in a house or a flat?"],"topicIntro":"Now let’s talk about clothes.","questions":["What kind of clothes do you usually wear?","Do you wear different clothes at the weekend from during the week?","How often do you buy new clothes?","Did you have to wear a uniform at school? [Why/Why not?]"],"model":"Q: What kind of clothes do you usually wear?\nA: Mostly casual things, to be honest: jeans, a plain shirt and trainers. My office doesn’t have a dress code, so I go for whatever is comfortable.\n\nQ: Do you wear different clothes at the weekend?\nA: A little. At the weekend I’m usually outdoors, so I wear sports clothes or an old jumper. I keep my smarter clothes for weddings and family dinners.\n\nQ: How often do you buy new clothes?\nA: Not very often, maybe three or four times a year. I’d rather buy one good jacket than five cheap ones that fall apart.\n\nQ: Did you have to wear a uniform at school?\nA: Yes, a grey one, and I hated it at the time. Looking back, though, it saved a lot of arguments in the morning.","moves":[{"label":{"en":"Answer first","tr":"Önce cevap","fa":"اول جواب"},"example":"Mostly casual things, to be honest."},{"label":{"en":"Add a reason or a detail","tr":"Bir neden ya da ayrıntı ekle","fa":"یک دلیل یا جزئیات اضافه کن"},"example":"My office doesn’t have a dress code, so I go for whatever is comfortable."},{"label":{"en":"A small contrast or a then/now","tr":"Küçük bir karşıtlık ya da o zaman/şimdi","fa":"یک تضاد کوچک یا «آن موقع/حالا»"},"example":"I hated it at the time. Looking back, though, it saved a lot of arguments."}],"selfCheck":[{"en":"I answered every question with two or three sentences, not one word.","tr":"Her soruyu tek kelimeyle değil, iki üç cümleyle cevapladım.","fa":"به هر سؤال با دو سه جمله جواب دادم، نه یک کلمه."},{"en":"I added a reason or a detail after each answer.","tr":"Her cevaptan sonra bir neden ya da ayrıntı ekledim.","fa":"بعد از هر جواب یک دلیل یا جزئیات اضافه کردم."},{"en":"I used the right tense: present for habits, past for school.","tr":"Doğru zamanı kullandım: alışkanlıklar için geniş zaman, okul için geçmiş zaman.","fa":"زمان درست را به کار بردم: حال برای عادت‌ها، گذشته برای مدرسه."}]},{"part":"Part 2","ctx":["S2-experience"],"minutes":[3,4],"title":{"en":"Part 2: a time you found your way","tr":"Part 2: yolunu bulduğun bir an","fa":"Part 2: وقتی راهت را پیدا کردی"},"examinerIntro":["Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. Before you talk, you’ll have one minute to think about what you’re going to say. You can make some notes if you wish. Do you understand?","Here’s some paper and a pencil for making notes, and here’s your topic. I’d like you to describe a time when you used a map or an app to find your way in a place you did not know.","All right? Remember you have one to two minutes for this. Don’t worry if I stop you. I’ll tell you when the time is up. Can you start speaking now, please?"],"card":{"task":"Describe a time when you used a map or an app to find your way in a place you did not know.","bullets":["where you were","what you were trying to find","how you used the map or app","and explain whether it helped you, and why"]},"prep":60,"talk":120,"roundingOff":["Do you usually plan your route before you go somewhere new?"],"model":"I’d like to talk about a trip to Lisbon two years ago, when I was trying to find a tiny family restaurant in the old town. A colleague had told me it served the best grilled fish in the city, and I was determined to find it.\n\nThe old town is a maze of steep, narrow streets, and they all look the same. At first I used the map app on my phone. I typed in the name and followed the blue arrow, and for about ten minutes everything went smoothly.\n\nThen, as I was climbing a long staircase between two buildings, the signal dropped. The arrow just froze, and I realised I had no idea which way I was facing. I tried the paper map from my hotel, but the smaller streets weren’t even on it.\n\nIn the end I did something very old-fashioned: I asked a waiter who was standing outside a café. He laughed, pointed to a church tower and told me to keep it on my left. Five minutes later I was sitting at the restaurant.\n\nSo did the app help? Only half. It got me close, but it couldn’t deal with those narrow streets, and the local knowledge was what really saved me. Looking back, I think that’s a good lesson: technology is great for the first ninety per cent of a journey, but sometimes you still need to talk to people.","moves":[{"label":{"en":"Start with the scene: where and what","tr":"Sahneyle başla: nerede ve ne","fa":"با صحنه شروع کن: کجا و چه"},"example":"I’d like to talk about a trip to Lisbon two years ago, when I was trying to find a tiny family restaurant."},{"label":{"en":"Tell the events in order, with a problem","tr":"Olayları sırayla, bir sorunla anlat","fa":"اتفاق‌ها را به ترتیب و با یک مشکل تعریف کن"},"example":"At first I used the map app... Then the signal dropped... In the end I asked a waiter."},{"label":{"en":"Spend time on the explain line","tr":"Açıklama satırına zaman ayır","fa":"روی خط توضیح وقت بگذار"},"example":"So did the app help? Only half... Looking back, I think that’s a good lesson."}],"selfCheck":[{"en":"I covered all four lines of the card and spoke for close to two minutes.","tr":"Kartın dört satırının hepsini ele aldım ve iki dakikaya yakın konuştum.","fa":"هر چهار خط کارت را گفتم و نزدیک دو دقیقه حرف زدم."},{"en":"I told the story in time order with at first, then, in the end.","tr":"Hikâyeyi at first, then, in the end ile zaman sırasına göre anlattım.","fa":"داستان را با at first، then و in the end به ترتیب زمان تعریف کردم."},{"en":"I used the past continuous for the scene and the past simple for the events.","tr":"Sahne için past continuous, olaylar için past simple kullandım.","fa":"برای صحنه از گذشته‌ی استمراری و برای اتفاق‌ها از گذشته‌ی ساده استفاده کردم."}]},{"part":"Part 3","ctx":["S3-tourism"],"minutes":[4,5],"title":{"en":"Part 3: travel information and tourist sites","tr":"Part 3: seyahat bilgisi ve turistik yerler","fa":"Part 3: اطلاعات سفر و جاذبه‌های گردشگری"},"examinerIntro":["We’ve been talking about finding your way in a new place, and I’d like to discuss with you one or two more general questions related to this."],"subtopics":[{"title":"Finding information when travelling","questions":["How do people usually find information about a place before they visit it?","Is information online more reliable than a printed guidebook? Why?","Why do some travellers prefer to explore a place without any plan?"]},{"title":"Tourist attractions","questions":["Why do some tourist attractions become extremely crowded?","Should famous sites limit the number of visitors each day?","What can local people gain from tourism in their area?"]}],"model":"Q: Should famous sites limit the number of visitors each day?\nA: In many cases, yes, I think they should. When too many people arrive at once, the place itself can be damaged, and nobody enjoys the visit. Venice is a good example: the city now charges day visitors at busy times to protect the historic centre. That said, limits can make a visit very expensive or hard to book, so the system needs to be fair to people who cannot plan months ahead.\n\nQ: What can local people gain from tourism in their area?\nA: The most obvious gain is jobs: hotels, restaurants and guides all depend on visitors. Tourism can also pay for things that locals use too, such as better public transport or restored buildings. On the other hand, if rents go up because flats are turned into holiday lets, local people may end up paying the price.","moves":[{"label":{"en":"Give a clear view","tr":"Net bir görüş ver","fa":"نظرت را روشن بگو"},"example":"In many cases, yes, I think they should."},{"label":{"en":"Support it: reason + example","tr":"Destekle: neden + örnek","fa":"پشتیبانی کن: دلیل + مثال"},"example":"When too many people arrive at once, the place can be damaged. Venice is a good example..."},{"label":{"en":"Show the other side","tr":"Karşı tarafı göster","fa":"طرف مقابل را نشان بده"},"example":"That said, limits can make a visit very expensive or hard to book..."}],"selfCheck":[{"en":"I gave a clear view in my first sentence.","tr":"İlk cümlemde net bir görüş verdim.","fa":"در جمله‌ی اولم نظر روشنی دادم."},{"en":"I supported it with a reason and a real example.","tr":"Onu bir neden ve gerçek bir örnekle destekledim.","fa":"آن را با یک دلیل و یک مثال واقعی پشتیبانی کردم."},{"en":"I talked about people in general, not only about myself.","tr":"Yalnızca kendimden değil, genel olarak insanlardan söz ettim.","fa":"درباره‌ی آدم‌ها به‌طور کلی حرف زدم، نه فقط خودم."}]}],"type":"sets","id":"c-x01-s-p","course":"ielts-exams","exam":"exam-01","unit":"x01-s"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"I usually wear casual clothes.\" Casual clothes are...","options":["clothes for formal events","comfortable, everyday clothes","a school uniform"],"correct":1,"why":{"en":"Casual = relaxed, not formal.","tr":"Casual = rahat, resmî olmayan.","fa":"casual یعنی راحت، غیررسمی."}},{"tests":"paraphrase","point":3,"prompt":"Which phrase means \"the place had too many visitors\"?","options":["it was overcrowded","it was deserted","it was well organised"],"correct":0,"why":{"en":"Overcrowded = too many people in one place.","tr":"Overcrowded = bir yerde çok fazla insan.","fa":"overcrowded یعنی آدم‌های خیلی زیاد در یک جا."}},{"tests":"method","point":2,"prompt":"You have one minute before your Part 2 talk. What is the best use of it?","options":["Write out the whole talk in full sentences","Sit quietly and wait","Write one key word for each line of the card"],"correct":2,"why":{"en":"Key words keep you on track; full sentences take too long and make you read aloud.","tr":"Anahtar kelimeler yolda kalmanı sağlar; tam cümleler çok uzun sürer ve sesli okumana yol açar.","fa":"کلیدواژه‌ها تو را در مسیر نگه می‌دارند؛ جمله‌ی کامل خیلی وقت می‌گیرد و باعث می‌شود از رو بخوانی."}},{"tests":"trap","point":2,"prompt":"After one minute of your Part 2 talk, you have covered the first three lines of the card. What do you do?","options":["Stop: you have answered the card","Keep going: explain whether it helped and why, with details","Start a new story"],"correct":1,"why":{"en":"The explain line is where you develop the talk to two minutes.","tr":"Açıklama satırı, konuşmayı iki dakikaya taşıdığın yerdir.","fa":"خط توضیح جایی است که صحبت را تا دو دقیقه گسترش می‌دهی."}},{"tests":"method","point":2,"prompt":"Part 3: \"Should famous sites charge higher prices?\" Which answer has the most complete structure?","options":["Partly. It protects the site, as in many old cities, but it may keep poorer visitors away.","Yes.","I went to a famous site last year and it was nice."],"correct":0,"why":{"en":"\"Partly...\" has a view, a reason, an example and the other side; the answer about last year’s visit talks only about the speaker.","tr":"\"Partly...\" cevabında görüş, neden, örnek ve karşı taraf var; geçen yılki ziyaretle ilgili cevap yalnızca konuşanın kendisinden söz ediyor.","fa":"جوابِ «Partly...» نظر، دلیل، مثال و طرف مقابل را دارد؛ جوابی که درباره‌ی بازدید پارسال است فقط از خود گوینده حرف می‌زند."}}],"id":"c-x01-s-x","course":"ielts-exams","exam":"exam-01","unit":"x01-s"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
